17	    }
18	
19	    @ExceptionHandler(ApiException.class)
20	    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
21	        return ResponseEntity.status(ex.status()).body(new ErrorBody(ex.code(), ex.getMessage()));
22	    }
23	
24	    @ExceptionHandler(MethodArgumentNotValidException.class)
25	    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
26	        String message = ex.getBindingResult().getFieldErrors().stream()
27	                .map(e -> e.getField() + " " + e.getDefaultMessage())
28	                .findFirst()
29	                .orElse("请求参数不合法");
30	        return ResponseEntity.badRequest().body(new ErrorBody("VALIDATION_FAILED", message));
31	    }
32	
33	    @ExceptionHandler(HttpMessageNotReadableException.class)
34	    public ResponseEntity<ErrorBody> handleNotReadable(HttpMessageNotReadableException ex) {
35	        return ResponseEntity.badRequest().body(new ErrorBody("BAD_REQUEST", "请求体无法解析"));
36	    }
37	
38	    @ExceptionHandler(Exception.class)
39	    public ResponseEntity<ErrorBody> handleOther(Exception ex) {
40	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
41	                .body(new ErrorBody("INTERNAL_ERROR", "服务内部错误"));
